// check_deadline: works out each pensioner's Life Certificate (Jeevan Pramaan) status.
// Rules: age 80+ can submit from 1 October, everyone else from 1 November. Deadline: 30 November.
// VERIFY ONCE: lc_verified_until after this year's deadline = done for the year, never reminded.
// WORKSPACES: only pensioners of signed-up workspaces (dataset w12...) are reminded; old sample rows are skipped.
const WS = Object.fromEntries($('Get workspaces').all().map(i => i.json).filter(w => w.key).map(w => [w.key, w]));
const active = r => !!r.dataset && r.dataset !== 'demo' && !!WS[r.dataset];

const OPEN_MONTH_80_PLUS = 10;
const OPEN_MONTH_OTHERS = 11;
const DEADLINE_MONTH = 11;
const DEADLINE_DAY = 30;
const URGENT_DAYS = 7;
const MISSED_REMINDER_DAYS = 14;

const zone = 'Asia/Kolkata';
const today = DateTime.now().setZone(zone).startOf('day');
const year = today.year;
const dayIn = v => v ? DateTime.fromISO(typeof v === 'string' ? v : new Date(v).toISOString()).setZone(zone).toISODate() : null;
const results = [];

for (const item of $('Get all pensioners').all()) {
  const p = item.json;
  if (!p.name || !active(p)) continue;
  const openMonth = p.age >= 80 ? OPEN_MONTH_80_PLUS : OPEN_MONTH_OTHERS;
  const openDate = DateTime.fromObject({ year, month: openMonth, day: 1 }, { zone });
  const deadline = DateTime.fromObject({ year, month: DEADLINE_MONTH, day: DEADLINE_DAY }, { zone });
  const daysLeft = Math.round(deadline.diff(today, 'days').days);
  const daysSinceOpen = Math.round(today.diff(openDate, 'days').days);
  const verifiedUntil = dayIn(p.lc_verified_until);
  const verified = !!verifiedUntil && verifiedUntil > deadline.toISODate();

  let status;
  if (verified) status = 'done';
  else if (today < openDate) status = 'not_open_yet';
  else if (daysLeft < 0) status = 'missed';
  else if (daysLeft <= URGENT_DAYS) status = 'urgent';
  else status = 'open';

  const shouldRemind =
    !!p.family_email && (
    status === 'urgent' ||
    (status === 'missed' && daysLeft >= -MISSED_REMINDER_DAYS) ||
    (status === 'open' && daysSinceOpen % 7 === 0));

  results.push({ json: { ...p, status, days_left: daysLeft, window_opens: openDate.toFormat('d LLLL yyyy'), deadline: deadline.toFormat('d LLLL yyyy'), verified_until: verifiedUntil, should_remind: shouldRemind } });
}

return results;

